rejectedModelSteps.formalStatement:
let LegalMove : ℕ → ℕ → Prop := fun N M => ∃ a b : ℕ, 0 < a ∧ 0 < b ∧ a ≠ b ∧ N = a * b ∧ M = Nat.dist a b;
let Win : ℕ → Prop := fun N => WellFounded.fix (measure_wf (fun N : ℕ => N)) (fun N rec => ∃ M : ℕ, LegalMove N M ∧ ∃ hMN : M < N, ¬ rec M hMN) N;
Win ((10 : ℕ) ^ 6)
